bad = []
for old, new in R:
    c = src.count(old)
    if c != 1:
        bad.append((c, old[:90]))
        continue
    src = src.replace(old, new)

if bad:
    for c, o in bad:
        print("MATCHED %d TIMES: %s" % (c, o))
    sys.exit("not written: %d replacement(s) did not match exactly once" % len(bad))

# keep the file's own line endings (universal-newline read turned CRLF into \n)
crlf = b"\r\n" in io.open(PATH, "rb").read(4096)
io.open(PATH, "w", encoding="utf-8", newline="\r\n" if crlf else "\n").write(src)
print("marker tags removed: %d   replacements: %d   wrote %s" % (n_pens, len(R), PATH))
